/**
 * When a framed page says the visitor is walking.
 *
 * The page around a frame steps its own bar aside while the visitor walks,
 * and cannot see for itself when that is. With a mouse it is while the
 * world holds the pointer. With thumbs there is no such thing: it is while
 * a thumb holds one of the two sticks the client draws. Both are told in
 * the same one word, on or off, and nothing else about what the visitor is
 * doing is.
 *
 * Read from the page's own document only: its pointer lock, and where on
 * the page a touch came down. Zero imports.
 */

/** The mark the client puts on each of its two thumb sticks (input/touchInput.ts). */
export const STICK_SELECTOR = '[data-webverse-stick]';

/** What is read of a pointer event: where it came down, and which pointer it is. */
interface PointerLike {
  target?: unknown;
  pointerId?: number;
}

/** The slice of `document` this needs. */
export interface WalkingDocument {
  pointerLockElement: unknown;
  addEventListener(type: string, listener: (event?: PointerLike) => void, capture?: boolean): void;
}

/**
 * Calls `say` each time the visitor starts or stops walking: on taking the
 * pointer into the world and letting it go, and on the first stick held
 * and the last one let go.
 */
export function reportWalking(doc: WalkingDocument, say: (walking: boolean) => void): void {
  doc.addEventListener('pointerlockchange', () => say(doc.pointerLockElement != null));

  /** The pointers now holding a stick. A touch that came down anywhere else is never among them. */
  const holding = new Set<number>();
  const onStick = (target: unknown): boolean => {
    try {
      return (target as { closest?(selector: string): unknown } | null | undefined)?.closest?.(STICK_SELECTOR) != null;
    } catch {
      return false;
    }
  };
  let heard = false;
  const down = (event?: PointerLike): void => {
    if (!heard) {
      // Once, in this page's own console: whether a press reaches the world inside its frame at all, and where.
      heard = true;
      console.info(`[webverse] frame: first press here, ${(event as { pointerType?: string } | undefined)?.pointerType ?? '?'}, on a stick: ${onStick(event?.target)}`);
    }
    if (event?.pointerId === undefined || !onStick(event.target)) return;
    holding.add(event.pointerId);
    if (holding.size === 1) say(true);
  };
  const up = (event?: PointerLike): void => {
    if (event?.pointerId === undefined || !holding.delete(event.pointerId)) return;
    if (holding.size === 0) say(false);
  };
  // Heard on the way down to the stick, so nothing the stick does with the event can keep it from being counted.
  doc.addEventListener('pointerdown', down, true);
  doc.addEventListener('pointerup', up, true);
  doc.addEventListener('pointercancel', up, true);
}

/** How seldom a drag over the page is told, in ms: a drag enters element after element as it moves. */
const DRAG_TOLD_EVERY_MS = 500;

/**
 * Calls `say` when a file is dragged over the page, which the page around
 * a frame cannot see: by the drag's types alone, so nothing in it is read.
 * A drag that carries no file is not told.
 */
export function reportFileDrags(doc: { addEventListener(type: string, listener: (event?: unknown) => void): void }, say: () => void): void {
  let told = -Infinity;
  doc.addEventListener('dragenter', (event) => {
    const types = (event as { dataTransfer?: { types?: ArrayLike<string> } } | undefined)?.dataTransfer?.types;
    if (!Array.from(types ?? []).includes('Files')) return;
    const now = Date.now();
    if (now - told < DRAG_TOLD_EVERY_MS) return;
    told = now;
    say();
  });
}
