/**
 * What a world frame says to the page around it.
 *
 * Messages go one way: from the frame to the page that embeds it. The one
 * exception is a fixed request with nothing in it, to show the client's own
 * settings, which a frame takes only when the page with the bar wraps it
 * (frameMenu.ts). There is nothing else the page around it can tell it, and
 * nothing secret for it to be told.
 *
 * A message is a plain object tagged `worldFrame: 1`, with a `type` and that
 * type's own fields:
 *
 *   ready    the frame page has started.
 *   status   `state` ('loading' | 'entered' | 'failed') and `url`: the world
 *            being opened, and for 'entered' the address its document really
 *            came from. A 'failed' may add `reason`: 'refused' when the
 *            world's host answered that this visitor may not read it,
 *            'unreachable' when no answer the frame may read came back,
 *            'web-page' when the address answered with a web page with no
 *            world in it (a door may lead to any address). An
 *            'entered' may add `vr: true`: the frame offers its own Enter VR
 *            button, and the page around it leaves room at the bar's end.
 *   title    `title`: the entered world's title.
 *   open     `url` and `gesture`: the world asks to go to a world on another
 *            source. `gesture` is true when a visitor used a door, false when
 *            a script asked.
 *   import   `state` ('ready' | 'opened' | 'failed'): sent only by the frame
 *            that shows a world made from a visitor's file (importFrame.ts).
 *            It is ready to be handed the world, has opened it, or could not.
 *            An 'opened' may add `vr: true`, as a status that a place was
 *            entered may.
 *   walking  `on`: the visitor has taken the pointer to walk and look, or
 *            has let it go. The page around the frame may put its own
 *            controls out of the way meanwhile.
 *   dragging a file is being dragged over the frame, which the page around
 *            it cannot see; it may put a place to drop it over the frame.
 *            Nothing of the drag is in it.
 *
 * The page around the frame reads a message field by field (`readFrameMessage`)
 * and keeps only the fields named here. Anything that is not exactly one of
 * these is not a message: it is ignored, never an error.
 *
 * Zero imports.
 */

export const FRAME_MESSAGE_TAG = 'worldFrame';
export const FRAME_MESSAGE_VERSION = 1;
/** The longest address a message may carry. */
export const MAX_ADDRESS_LENGTH = 4096;
/** The longest title a message may carry. */
export const MAX_TITLE_LENGTH = 200;

export type FrameStatus = 'loading' | 'entered' | 'failed';

/** Why a load failed, where the page around the frame has something to say about it. */
export type FailureReason = 'refused' | 'unreachable' | 'web-page';
export type ImportState = 'ready' | 'opened' | 'failed';

export type FrameMessage =
  | { type: 'ready' }
  | { type: 'status'; state: FrameStatus; url: string; reason?: FailureReason; vr?: true }
  | { type: 'title'; title: string }
  | { type: 'open'; url: string; gesture: boolean }
  | { type: 'import'; state: ImportState; vr?: true }
  | { type: 'walking'; on: boolean }
  | { type: 'dragging' };

/** `message` as the frame posts it. A title longer than the limit is cut. */
export function frameMessage(message: FrameMessage): Record<string, unknown> {
  const cut = message.type === 'title' ? { ...message, title: message.title.slice(0, MAX_TITLE_LENGTH) } : message;
  return { [FRAME_MESSAGE_TAG]: FRAME_MESSAGE_VERSION, ...cut };
}

const isAddress = (value: unknown): value is string => typeof value === 'string' && value.length > 0 && value.length <= MAX_ADDRESS_LENGTH;

/**
 * The message in `data`, or null when `data` is not one. Never throws, and
 * the answer is a new object holding only the message's own fields.
 */
export function readFrameMessage(data: unknown): FrameMessage | null {
  try {
    if (typeof data !== 'object' || data === null || Array.isArray(data)) return null;
    const fields = data as Record<string, unknown>;
    if (fields[FRAME_MESSAGE_TAG] !== FRAME_MESSAGE_VERSION) return null;
    const { type, state, url, title, gesture, reason, on, vr } = fields;
    if (type === 'walking') return typeof on === 'boolean' ? { type, on } : null;
    if (type === 'ready') return { type };
    if (type === 'dragging') return { type };
    if (type === 'status') {
      if (!(state === 'loading' || state === 'entered' || state === 'failed') || !isAddress(url)) return null;
      // A reason is one of two words or it is not there: no text of the frame's own rides in on it.
      if (state === 'entered' && vr === true) return { type, state, url, vr };
      return state === 'failed' && (reason === 'refused' || reason === 'unreachable' || reason === 'web-page') ? { type, state, url, reason } : { type, state, url };
    }
    if (type === 'title') return typeof title === 'string' && title.length <= MAX_TITLE_LENGTH ? { type, title } : null;
    if (type === 'open') return isAddress(url) && typeof gesture === 'boolean' ? { type, url, gesture } : null;
    if (type === 'import') {
      if (state === 'opened' && vr === true) return { type, state, vr };
      return state === 'ready' || state === 'opened' || state === 'failed' ? { type, state } : null;
    }
    return null;
  } catch {
    return null;
  }
}

/** The text a message carries, in characters: what a frame is charged for sending it. */
export function frameMessageSize(message: FrameMessage): number {
  if (message.type === 'ready' || message.type === 'import' || message.type === 'walking' || message.type === 'dragging') return 0;
  return message.type === 'title' ? message.title.length : message.url.length;
}
